import java.io.*;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in, 1 << 16);
        private final byte[] buffer = new byte[1 << 16];
        private int pos = 0;
        private int len = 0;

        private int read() throws IOException {
            if (pos >= len) {
                len = in.read(buffer);
                pos = 0;
                if (len == -1) return -1;
            }
            return buffer[pos++] & 0xff;
        }

        int nextChar() throws IOException {
            int c = read();
            while (c != -1 && c <= 32) c = read();
            return c;
        }

        int nextInt() throws IOException {
            int c = read();
            while (c != -1 && c <= 32) c = read();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c != -1 && c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();
        int P = fs.nextInt();

        int[] row = new int[N + 1];
        for (int i = 1; i <= N; i++) row[i] = i;

        int[] col = new int[M + 1];
        for (int i = 1; i <= M; i++) col[i] = i;

        for (int step = 0; step < P; step++) {
            int op = fs.nextInt();
            int a = fs.nextInt();
            int b = fs.nextInt();

            if (op == 'L') {
                int tmp = row[a];
                row[a] = row[b];
                row[b] = tmp;
            } else {
                int tmp = col[a];
                col[a] = col[b];
                col[b] = tmp;
            }
        }

        StringBuilder sb = new StringBuilder(N * M * 8);

        for (int i = 1; i <= N; i++) {
            long originalRow = row[i];
            long base = (originalRow - 1) * M;

            for (int j = 1; j <= M; j++) {
                if (j > 1) sb.append(' ');
                sb.append(base + col[j]);
            }
            sb.append('\n');
        }

        System.out.print(sb);
    }
}
